FIXED_LEVELS = [{'cells': [43, 44, 51, 52, 59, 60], 'walls': [], 'bonds': [[0, 1], [0, 2], [1, 3], [2, 3], [2, 4], [3, 5], [4, 5]], 'notches': [[4, 3]], 'goal': [51, 52, 59, 60]}, {'cells': [34, 35, 36, 37, 42, 43, 44, 45, 50, 51, 52, 53], 'walls': [58, 61], 'bonds': [[0, 1], [0, 4], [1, 2], [1, 5], [2, 3], [2, 6], [3, 7], [4, 5], [4, 8], [5, 6], [5, 9], [6, 7], [6, 10], [7, 11], [8, 9], [9, 10], [10, 11]], 'notches': [[1, 1], [4, 3]], 'goal': [36, 37, 42, 44, 45, 50, 52, 53]}, {'cells': [18, 19, 20, 21, 22, 26, 27, 28, 29, 30, 34, 35, 36, 37, 38, 42, 43, 44, 45, 46], 'walls': [50, 52, 57, 58, 59, 60], 'bonds': [[0, 1], [0, 5], [1, 2], [1, 6], [2, 3], [2, 7], [3, 4], [3, 8], [4, 9], [5, 6], [5, 10], [6, 7], [6, 11], [7, 8], [7, 12], [8, 9], [8, 13], [9, 14], [10, 11], [10, 15], [11, 12], [11, 16], [12, 13], [12, 17], [13, 14], [13, 18], [14, 19], [15, 16], [16, 17], [17, 18], [18, 19]], 'notches': [[0, 0], [10, 2], [9, 1], [19, 1], [14, 2], [2, 1]], 'goal': [26, 27, 34, 35, 42, 43, 45, 46, 53, 54, 61, 62]}, {'cells': [18, 19, 20, 21, 22, 26, 27, 28, 29, 30, 34, 35, 36, 37, 38, 42, 43, 44, 45, 46], 'walls': [51, 57, 59], 'bonds': [[0, 1], [0, 5], [1, 2], [1, 6], [2, 3], [2, 7], [3, 4], [3, 8], [4, 9], [5, 6], [5, 10], [6, 7], [6, 11], [7, 8], [7, 12], [8, 9], [8, 13], [9, 14], [10, 11], [10, 15], [11, 12], [11, 16], [12, 13], [12, 17], [13, 14], [13, 18], [14, 19], [15, 16], [16, 17], [17, 18], [18, 19]], 'notches': [[14, 2], [1, 3], [10, 3], [2, 0], [7, 1], [8, 2]], 'goal': [26, 27, 34, 35, 42, 43, 45, 46, 53, 54, 61, 62]}, {'cells': [25, 26, 27, 28, 29, 33, 34, 35, 36, 37, 41, 42, 43, 44, 45, 49, 50, 51, 52, 53], 'walls': [56, 58, 61], 'bonds': [[0, 1], [0, 5], [1, 2], [1, 6], [2, 3], [2, 7], [3, 4], [3, 8], [4, 9], [5, 6], [5, 10], [6, 7], [6, 11], [7, 8], [7, 12], [8, 9], [8, 13], [9, 14], [10, 11], [10, 15], [11, 12], [11, 16], [12, 13], [12, 17], [13, 14], [13, 18], [14, 19], [15, 16], [16, 17], [17, 18], [18, 19]], 'notches': [[12, 2], [18, 3], [16, 1], [9, 1], [13, 1], [11, 2], [2, 1]], 'goal': [36, 37, 41, 42, 44, 45, 49, 50, 52, 53, 57, 59]}, {'cells': [25, 26, 27, 28, 29, 33, 34, 35, 36, 37, 41, 42, 43, 44, 45, 49, 50, 51, 52, 53], 'walls': [57, 60, 61, 62], 'bonds': [[0, 1], [0, 5], [1, 2], [1, 6], [2, 3], [2, 7], [3, 4], [3, 8], [4, 9], [5, 6], [5, 10], [6, 7], [6, 11], [7, 8], [7, 12], [8, 9], [8, 13], [9, 14], [10, 11], [10, 15], [11, 12], [11, 16], [12, 13], [12, 17], [13, 14], [13, 18], [14, 19], [15, 16], [16, 17], [17, 18], [18, 19]], 'notches': [[16, 1], [3, 0], [14, 2], [7, 1], [18, 1], [15, 3], [5, 1]], 'goal': [33, 34, 35, 37, 41, 42, 44, 45, 49, 53, 59]}, {'cells': [17, 18, 19, 20, 25, 26, 27, 28, 33, 34, 35, 36, 41, 42, 43, 44], 'walls': [49, 50, 54, 55, 57, 58, 61, 62, 63], 'bonds': [[0, 1], [0, 4], [1, 2], [1, 5], [2, 3], [2, 6], [3, 7], [4, 5], [4, 8], [5, 6], [5, 9], [6, 7], [6, 10], [7, 11], [8, 9], [8, 12], [9, 10], [9, 13], [10, 11], [10, 14], [11, 15], [12, 13], [13, 14], [14, 15]], 'notches': [[15, 2], [12, 0], [1, 0], [9, 2], [5, 1], [7, 2], [2, 1]], 'goal': [25, 33, 34, 42, 52, 60]}]

N=8
DIRS=((0,-1),(0,1),(-1,0),(1,0))

def initial(cfg):return tuple(cfg['cells'])

def components(cfg,state):
    live={i for i,p in enumerate(state) if p>=0};out=[]
    bonds=cfg['bonds']
    while live:
        todo=[min(live)];part=set(todo);live.remove(todo[0])
        while todo:
            a=todo.pop()
            for x,y in bonds:
                b=y if x==a else x if y==a else -1
                if b in live:live.remove(b);part.add(b);todo.append(b)
        out.append(tuple(sorted(part)))
    return out

def settle(cfg,state):
    state=tuple(state);walls=set(cfg['walls'])
    while True:
        groups=components(cfg,state);owner={state[i]:g for g,part in enumerate(groups) for i in part}
        blocked=set()
        for g,part in enumerate(groups):
            if any(state[i]//N==N-1 or state[i]+N in walls for i in part):blocked.add(g)
        changed=True
        while changed:
            changed=False
            for g,part in enumerate(groups):
                if g in blocked:continue
                if any(owner.get(state[i]+N) in blocked for i in part):blocked.add(g);changed=True
        movers={i for g,part in enumerate(groups) if g not in blocked for i in part}
        if not movers:return state
        state=tuple(p+N if i in movers else p for i,p in enumerate(state))

def advance(cfg,state,notch,gravity=True):
    marks=dict(cfg['notches'])
    if notch not in marks or state[notch]<0:return state
    dx,dy=DIRS[marks[notch]];pos=state[notch];occupied={p:i for i,p in enumerate(state) if p>=0};removed=set()
    x,y=pos%N,pos//N
    while 0<=x<N and 0<=y<N and y*N+x in occupied:
        removed.add(occupied[y*N+x]);x+=dx;y+=dy
    nxt=tuple(-1 if i in removed else p for i,p in enumerate(state))
    return settle(cfg,nxt) if gravity else nxt

def solved(cfg,state):return sorted(p for p in state if p>=0)==sorted(cfg['goal'])

def make_cfg(cells,walls,notches):
    cells=sorted(cells);idx={p:i for i,p in enumerate(cells)}
    bonds=[]
    for p,i in idx.items():
        for q in (p+1 if p%N<N-1 else -1,p+N):
            if q in idx:bonds.append([i,idx[q]])
    return {'cells':cells,'walls':sorted(walls),'bonds':bonds,'notches':[[idx[p],d] for p,d in notches],'goal':[]}

import numpy as np
from arcengine import ARCBaseGame,Camera,Level,Sprite,GameAction

class Sg16(ARCBaseGame):
    def __init__(self,seed=0):
        self.cfg=None;self.state=None;self.history=[];self.pending=None
        levels=[Level(sprites=[Sprite(pixels=np.zeros((64,64),dtype=np.int64),name='fault')],grid_size=(64,64),data={'layout':c},name='Fault %d'%(i+1)) for i,c in enumerate(FIXED_LEVELS)]
        super().__init__(game_id='sg16-v1',levels=levels,camera=Camera(background=5,letter_box=5),available_actions=[6,7],seed=seed)

    def on_set_level(self,level):
        self.cfg=level.get_data('layout');self.state=initial(self.cfg);self.history=[];self.pending=None;self._paint()

    def step(self):
        if self.pending is not None:
            self.state=self.pending;self.pending=None;self._paint()
            if solved(self.cfg,self.state):self.next_level()
            self.complete_action();return
        a=0 if self.action.id==GameAction.RESET else int(self.action.id.name[-1])
        if a==7 and self.history:self.state=self.history.pop()
        elif a==6:
            d=self.action.data or {};x,y=d.get('x',-1),d.get('y',-1)
            if type(x) is int and type(y) is int and 8<=x<56 and 8<=y<56:
                p=((y-8)//6)*8+(x-8)//6
                for i,direction in self.cfg['notches']:
                    if self.state[i]==p:
                        nxt=advance(self.cfg,self.state,i)
                        if nxt!=self.state:
                            self.history.append(self.state)
                            self.pending=nxt;self.state=advance(self.cfg,self.state,i,gravity=False)
                            self._paint();return
                        break
        self._paint()
        if solved(self.cfg,self.state):self.next_level()
        self.complete_action()

    def _paint(self):
        c=np.full((64,64),5,dtype=np.int64);goal=set(self.cfg['goal'])
        c[57,7:57]=3
        for p in self.cfg['walls']:
            x,y=8+(p%8)*6,8+(p//8)*6;c[y:y+6,x:x+6]=3;c[y+2:y+4,x+2:x+4]=4
        for p in goal:
            x,y=8+(p%8)*6,8+(p//8)*6;c[y:y+6,x:x+6]=4
        for group in components(self.cfg,self.state):
            positions={self.state[i] for i in group}
            for p in positions:
                x,y=8+(p%8)*6,8+(p//8)*6;c[y:y+6,x:x+6]=10
                if p%8==0 or p-1 not in positions:c[y:y+6,x]=1
                if p%8==7 or p+1 not in positions:c[y:y+6,x+5]=1
                if p-8 not in positions:c[y,x:x+6]=1
                if p+8 not in positions:c[y+5,x:x+6]=1
        # Continuous target silhouette remains legible over the solid material.
        for p in goal:
            x,y=8+(p%8)*6,8+(p//8)*6
            if p%8==0 or p-1 not in goal:c[y:y+6,x]=11
            if p%8==7 or p+1 not in goal:c[y:y+6,x+5]=11
            if p-8 not in goal:c[y,x:x+6]=11
            if p+8 not in goal:c[y+5,x:x+6]=11
        for i,d in self.cfg['notches']:
            p=self.state[i]
            if p<0:continue
            x,y=8+(p%8)*6,8+(p//8)*6
            # A notch is a slit in the material, not a movement arrow.
            # The short crack points into the contiguous strip it will cut.
            dx,dy=DIRS[d]
            c[y+2:y+4,x+2:x+4]=0
            for t in range(1,4):
                xx,yy=x+3+dx*t,y+3+dy*t
                if 0<=xx<64 and 0<=yy<64:c[yy,xx]=5
            if dx:c[y+1:y+5,x+2]=0
            else:c[y+2,x+1:x+5]=0
        self.current_level.remove_all_sprites();self.current_level.add_sprite(Sprite(pixels=c,name='falling-fracture',x=0,y=0,layer=0))
